export const TYPES=['cockpit','habitat','cargo','reactor','engine','collar','wing','solar','antenna'];
export function random(seed){let h=2166136261;for(const c of String(seed)){h^=c.charCodeAt(0);h=Math.imul(h,16777619);}return()=>{h+=0x6D2B79F5;let t=h;t=Math.imul(t^t>>>15,t|1);t^=t+Math.imul(t^t>>>7,t|61);return((t^t>>>14)>>>0)/4294967296;};}
export function blueprint(seed,role='explorer',count=4){const r=random(seed+'|'+role+'|'+count),parts=[];let z=0;const add=(type,length,x=0,y=0,at=z,side=0)=>{parts.push({id:parts.length,type,length,x,y,z:at,side,variant:Math.floor(r()*3)});};add('cockpit',2);z+=2;for(let i=0;i<count;i++){const type=role==='freighter'?'cargo':r()<.45?'habitat':'reactor';add(type,2.4);add('collar',.22,0,0,z-1.2);if(i===1||i===count-1){const type=role==='scout'?'wing':'solar';for(const side of [-1,1])add(type,2,side*1.15,0,z,side);}z+=2.4;}add('collar',.22,0,0,z-1.2);add('engine',2.6);if(role==='freighter')for(const side of [-1,1])add('engine',2.6,side*1.8,0,z,side);add('antenna',1,0,1.1,2.8);return {version:1,seed:String(seed),role,count,parts};}
